INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('58587bc7-c34a-4cff-834a-6abdb165c3ad', 'c3c3c3c3-3030-4000-8000-000000000003', 19, 'Dia 19 — Perspectiva', 'Semana 3: Discernir', '{"pch": "Os meus pensamentos n\u00e3o s\u00e3o os vossos pensamentos\u2026 \u00c0s vezes, clareza \u00e9 aceitar que voc\u00ea n\u00e3o v\u00ea tudo.", "verse": "Is 55,8-9", "lectio": "Leia Is 55,6-11. A palavra que n\u00e3o volta vazia.", "practice": "Escreva sua situa\u00e7\u00e3o atual como se fosse Deus descrevendo-a para voc\u00ea.", "question": "O que mudaria se voc\u00ea visse sua situa\u00e7\u00e3o do ponto de vista de Deus?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;